//! Compares every case of `tests/data/num/corpus.txt` (generated by qjs, see
//! `tests/data/num/gen-corpus.js`) with our implementation.

extern crate std;

use super::*;
use std::format;
use std::string::{String, ToString};
use std::vec::Vec;

const CORPUS: &str = include_str!("../../../../tests/data/num/corpus.txt");

fn f64_from_hex(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).unwrap())
}

/// Decodes a JSON string literal (as written by JSON.stringify) to UTF-16.
fn json_string(s: &str) -> Vec<u16> {
    let inner = &s[1..s.len() - 1];
    let mut out = Vec::new();
    let mut chars = inner.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            let mut buf = [0u16; 2];
            out.extend_from_slice(c.encode_utf16(&mut buf));
            continue;
        }
        match chars.next().unwrap() {
            'u' => {
                let hex: String = chars.by_ref().take(4).collect();
                out.push(u16::from_str_radix(&hex, 16).unwrap());
            }
            'n' => out.push(0x0A),
            't' => out.push(0x09),
            'r' => out.push(0x0D),
            'b' => out.push(0x08),
            'f' => out.push(0x0C),
            c => out.push(c as u16),
        }
    }
    out
}

fn result<const N: usize>(r: Result<NumStr<N>, RangeError>) -> String {
    match r {
        Ok(s) => s.as_str().to_string(),
        Err(_) => "!RangeError".to_string(),
    }
}

fn arg(s: &str) -> Option<i32> {
    if s == "u" {
        None
    } else {
        Some(s.parse().unwrap())
    }
}

fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits() || (a.is_nan() && b.is_nan())
}

/// Runs a parser on the UTF-16 input and, if it is Latin-1, on that too.
fn parse_both(input: &[u16], f: impl Fn(Parsed<'_>) -> f64) -> Result<f64, String> {
    let wide = f(Parsed::Wide(input));
    if input.iter().all(|&c| c < 256) {
        let narrow: Vec<u8> = input.iter().map(|&c| c as u8).collect();
        let n = f(Parsed::Narrow(&narrow));
        if !same(n, wide) {
            return Err(format!("u8 gives {n:e}, u16 gives {wide:e}"));
        }
    }
    Ok(wide)
}

#[derive(Clone, Copy)]
enum Parsed<'a> {
    Narrow(&'a [u8]),
    Wide(&'a [u16]),
}

#[test]
fn qjs_corpus() {
    let count = check_corpus(CORPUS);
    assert!(count > 20_000, "corpus too small: {count}");
}

/// A larger corpus made out of tree (see `gen-corpus.js`), named by `DJS_NUM_CORPUS`.
#[test]
#[ignore]
fn qjs_corpus_external() {
    let path = std::env::var("DJS_NUM_CORPUS").expect("set DJS_NUM_CORPUS");
    let text = std::fs::read_to_string(path).unwrap();
    let count = check_corpus(&text);
    std::println!("{count} cases match");
}

/// Checks every line, panicking with the first differences. Returns the number of cases.
fn check_corpus(corpus: &str) -> usize {
    let mut failures = Vec::new();
    let mut count = 0;
    for line in corpus.lines() {
        let cols: Vec<&str> = line.split('\t').collect();
        count += 1;
        let (got, expect) = match cols[0] {
            "str" => (
                to_string(f64_from_hex(cols[1])).as_str().to_string(),
                cols[2].to_string(),
            ),
            "radix" => (
                result(to_string_radix(
                    f64_from_hex(cols[1]),
                    cols[2].parse().unwrap(),
                )),
                cols[3].to_string(),
            ),
            "fixed" => (
                result(to_fixed(f64_from_hex(cols[1]), cols[2].parse().unwrap())),
                cols[3].to_string(),
            ),
            "exp" => (
                result(to_exponential(f64_from_hex(cols[1]), arg(cols[2]))),
                cols[3].to_string(),
            ),
            "prec" => (
                result(to_precision(f64_from_hex(cols[1]), arg(cols[2]))),
                cols[3].to_string(),
            ),
            "num" | "pf" | "pi" => {
                let input = json_string(cols[1]);
                let radix: i32 = if cols[0] == "pi" {
                    cols[2].parse().unwrap()
                } else {
                    0
                };
                let expect = f64_from_hex(cols[cols.len() - 1]);
                let got = parse_both(&input, |s| match (cols[0], s) {
                    ("num", Parsed::Narrow(s)) => string_to_number(s),
                    ("num", Parsed::Wide(s)) => string_to_number(s),
                    ("pf", Parsed::Narrow(s)) => parse_float(s),
                    ("pf", Parsed::Wide(s)) => parse_float(s),
                    (_, Parsed::Narrow(s)) => parse_int(s, radix),
                    (_, Parsed::Wide(s)) => parse_int(s, radix),
                });
                match got {
                    Ok(g) if same(g, expect) => continue,
                    Ok(g) => (format!("{g:e}"), format!("{expect:e}")),
                    Err(e) => (e, format!("{expect:e}")),
                }
            }
            other => panic!("unknown corpus op {other}"),
        };
        if got != expect {
            failures.push(format!("{line}\n    got: {got}"));
        }
    }
    if !failures.is_empty() {
        let shown: Vec<&String> = failures.iter().take(30).collect();
        panic!(
            "{} of {count} corpus cases differ from qjs:\n{}",
            failures.len(),
            shown
                .iter()
                .map(|s| s.as_str())
                .collect::<Vec<_>>()
                .join("\n")
        );
    }
    count
}
